    sections.append('<section class="museum" id="'+e(mu['slug'])+'" data-state="'+e(mu['state'])+'" data-search="'+e(search)+'"><div class="museum-picture">'+figure(show)+'</div><div class="museum-content"><p class="location">'+e(mu['state']+' / '+mu['city'])+'</p><h3>'+e(mu['name'])+'</h3><p class="intro">'+e(intros[mu['slug']])+'</p><p class="count">'+str(len(fs))+' selected works · '+str(len(illustrated))+' pictures · holdings / documented loans; current display not asserted</p><p>'+link(mu['website_url'],'Explore the museum’s collection source')+'</p><details><summary>View all '+str(len(fs))+' artworks and their evidence</summary>'+''.join(work(f)for f in fs)+'</details></div></section>')
